class Solution { public: vector<vector<string>> displayTable(vector<vector<string>>& orders){set<string> foods;map<int,unordered_map<string,int>> tables;for(auto& order:orders){int table=stoi(order[1]);foods.insert(order[2]);++tables[table][order[2]];}vector<vector<string>> answer;vector<string> header{"Table"};header.insert(header.end(),foods.begin(),foods.end());answer.push_back(header);for(auto& [table,count]:tables){vector<string> row{to_string(table)};for(auto& food:foods)row.push_back(to_string(count[food]));answer.push_back(row);}return answer;} };
